#include "bch511385.h"

#include <stdint.h>
#include <stdio.h>

// 3 known-answer vectors: 385-bit message -> 511-bit systematic codeword.
// Bit 0 is the first (highest-order) bit, exactly as the API uses them.
// Generated by an independent GF(2^9) reference and cross-checked bit-for-bit.
static const char *const kat_msg[3] = {
    "",
    "",
    "",
};
static const char *const kat_cw[3] = {
    "",
    "",
    "",
};

// 6-bit error pattern applied to kat_cw[0] (decoder must restore it exactly)
static const int kat_err_pos[6] = {0, 63, 127, 255, 384, 510};


//
// Deterministic PRNG so a failing run can be reproduced exactly.
//
static uint32_t g_state = 0x12345678u;
static uint32_t xs32(void) {
    g_state ^= g_state << 13;
    g_state ^= g_state >> 17;
    g_state ^= g_state << 5;
    return g_state;
}

//
// Flip exactly n distinct bit positions in a BCH_N word.
// The original demo used bits[rand()%511] ^= 1, which picks with replacement:
// about one codeword in six then got fewer than n real errors, so the failure
// rate it printed was optimistic.
//
static void add_errors(uint8_t *bits, int n) {
    int used[BCH_N] = {0};
    int placed = 0;
    while (placed < n) {
        int p = (int)(xs32() % BCH_N);
        if (!used[p]) {
            used[p] = 1;
            bits[p] ^= 1;
            placed++;
        }
    }
}

static bool case_known_answers(void) {
    for (int v = 0; v < 3; v++) {
        uint8_t bits[BCH_N];
        for (int i = 0; i < BCH_N; i++) bits[i] = (uint8_t)(kat_cw[v][i] - '0');
        if (!bch511385_check(bits)) {
            printf("FAIL: known-answer vector %d is not a valid codeword\n", v);
            return false;
        }
        for (int i = 0; i < BCH_K; i++)
            if (bits[i] != (uint8_t)(kat_msg[v][i] - '0')) {
                printf("FAIL: known-answer vector %d message bits were modified\n", v);
                return false;
            }
    }
    return true;
}

static bool case_known_correction(void) {
    uint8_t bits[BCH_N];
    for (int i = 0; i < BCH_N; i++) bits[i] = (uint8_t)(kat_cw[0][i] - '0');
    for (int i = 0; i < 6; i++) bits[kat_err_pos[i]] ^= 1;
    int r = bch511385_decode(bits);
    if (r != 6) {
        printf("FAIL: known 6-error case returned %d, expected 6\n", r);
        return false;
    }
    for (int i = 0; i < BCH_N; i++)
        if (bits[i] != (uint8_t)(kat_cw[0][i] - '0')) {
            printf("FAIL: known 6-error case did not restore the codeword (bit %d)\n", i);
            return false;
        }
    return true;
}

static bool case_clean_is_untouched(void) {
    uint8_t bits[BCH_N], copy[BCH_N];
    for (int i = 0; i < BCH_K; i++) bits[i] = (uint8_t)(xs32() & 1);
    bch511385_encode(bits);
    for (int i = 0; i < BCH_N; i++) copy[i] = bits[i];

    if (bch511385_decode(bits) != 0) {
        printf("FAIL: clean codeword did not return 0\n");
        return false;
    }
    for (int i = 0; i < BCH_N; i++)
        if (bits[i] != copy[i]) {
            printf("FAIL: clean codeword was modified by decode (bit %d)\n", i);
            return false;
        }
    return true;
}

static bool case_check_rejects_errors(void) {
    uint8_t bits[BCH_N];
    for (int i = 0; i < BCH_K; i++) bits[i] = (uint8_t)(xs32() & 1);
    bch511385_encode(bits);
    if (!bch511385_check(bits)) {
        printf("FAIL: freshly encoded word rejected\n");
        return false;
    }
    for (int e = 1; e <= 5; e++) {
        int p = (int)(xs32() % BCH_N);
        bits[p] ^= 1;
        if (bch511385_check(bits)) {
            printf("FAIL: check accepted a word with %d error(s)\n", e);
            return false;
        }
    }
    return true;
}

static bool case_encoders_agree(void) {
    for (int t = 0; t < 50; t++) {
        uint8_t a[BCH_N], b[BCH_N];
        for (int i = 0; i < BCH_K; i++) {
            uint8_t bit = (uint8_t)(xs32() & 1);
            a[i] = bit;
            b[i] = bit;
        }
        for (int i = BCH_K; i < BCH_N; i++) {
            a[i] = 0;
            b[i] = 0;
        }
        bch511385_encode(a);
        bch511385_encode_fast(b);
        for (int i = 0; i < BCH_N; i++)
            if (a[i] != b[i]) {
                printf("FAIL: encode and encode_fast disagree at bit %d\n", i);
                return false;
            }
    }
    return true;
}

static bool case_round_trip(int n_errors, int trials) {
    for (int t = 0; t < trials; t++) {
        uint8_t bits[BCH_N], original[BCH_N];
        for (int i = 0; i < BCH_K; i++) bits[i] = (uint8_t)(xs32() & 1);
        bch511385_encode(bits);
        for (int i = 0; i < BCH_N; i++) original[i] = bits[i];

        add_errors(bits, n_errors);
        int r = bch511385_decode(bits);

        if (r < 0 || r > n_errors) {
            printf("FAIL: %d errors: decode returned %d\n", n_errors, r);
            return false;
        }
        for (int i = 0; i < BCH_N; i++)
            if (bits[i] != original[i]) {
                printf("FAIL: %d errors: bit %d wrong after decode\n", n_errors, i);
                return false;
            }
    }
    return true;
}

static bool case_beyond_t_is_flagged(int n_errors, int trials) {
    for (int t = 0; t < trials; t++) {
        uint8_t bits[BCH_N], received[BCH_N];
        for (int i = 0; i < BCH_K; i++) bits[i] = (uint8_t)(xs32() & 1);
        bch511385_encode(bits);

        add_errors(bits, n_errors);
        // Snapshot the corrupted word: when the decoder gives up, the contract is
        // that it leaves the received bits alone, not that it restores them.
        for (int i = 0; i < BCH_N; i++) received[i] = bits[i];

        int r = bch511385_decode(bits);

        if (r > BCH_T) {
            printf("FAIL: %d errors reported as %d corrected (> t)\n", n_errors, r);
            return false;
        }
        if (r < 0) {
            // Uncorrectable: the buffer must still hold exactly what came in.
            for (int i = 0; i < BCH_N; i++)
                if (bits[i] != received[i]) {
                    printf("FAIL: %d errors: uncorrectable but buffer was modified\n", n_errors);
                    return false;
                }
        }
        // r in 0..14 here means a miscorrection. That is theoretically possible
        // above t and is not a decoder bug (BCH cannot detect it), so it is not
        // counted as a failure; a real deployment should add its own checks.
    }
    return true;
}

int main(void) {
    bch511385_init();

    bool kat_ok = case_known_answers();
    bool kat_fix = case_known_correction();
    bool clean_ok = case_clean_is_untouched();
    bool check_ok = case_check_rejects_errors();
    bool enc_ok = case_encoders_agree();

    bool round_ok = true;
    for (int n = 0; n <= BCH_T; n++) {
        if (!case_round_trip(n, n == 0 ? 50 : 100)) {
            printf("  (round trip failed at %d errors)\n", n);
            round_ok = false;
        }
    }

    bool beyond_ok = true;
    const int beyond[] = {15, 16, 17, 20, 28, 29};
    for (unsigned i = 0; i < sizeof(beyond) / sizeof(beyond[0]); i++)
        if (!case_beyond_t_is_flagged(beyond[i], 20)) beyond_ok = false;

    struct {
        const char *name;
        bool ok;
    } results[] = {
        {"known-answer vectors", kat_ok},
        {"known 6-error correction", kat_fix},
        {"clean codeword untouched", clean_ok},
        {"check() rejects errors", check_ok},
        {"encode paths agree", enc_ok},
        {"round trip 0..14 errors", round_ok},
        {"15..29 errors flagged", beyond_ok},
    };

    int failures = 0;
    for (unsigned i = 0; i < sizeof(results) / sizeof(results[0]); i++) {
        if (!results[i].ok) failures++;
        printf("%-26s %s\n", results[i].name, results[i].ok ? "ok" : "FAIL");
    }
    printf("\n%s (%d failure%s)\n", failures ? "FAILED" : "all tests passed", failures,
           failures == 1 ? "" : "s");
    return failures ? 1 : 0;
}
